import Foundation
import Testing
import AetherLibavformat
import AetherLibavcodec
import AetherLibavutil

/// Proves the mov lazy_frag_index patch (build.sh `patch_ffmpeg_mov_lazy_frag_index`,
/// patches/mov-lazy-frag-index.patch) is in the shipped libavformat, and that a seek with it
/// lands where the full fragment index lands.
///
/// The fixture is a 12 s fragmented MP4 (16x16 H.264 with B-frames, a keyframe every 2 s,
/// 8 kHz mono AAC) cut into 1 s fragments, so most fragments do not start with a sync sample.
/// Its first fragment is in the moov, so an mdat sits in front of the first moof, and it ends
/// with an mfra. Two seeks on it went wrong before the fix that followed PR 14: a video seek
/// read one fragment's mdat as the successor of a later fragment, and reading then switched to
/// that fragment forever; a forward seek on the audio stream let the video start on the first
/// sample it read, which was not a sync sample. Regenerate with:
///
///     ffmpeg -f lavfi -i testsrc=size=16x16:rate=5 -f lavfi -i sine=frequency=440:sample_rate=8000 \
///       -t 12 -c:v libx264 -preset ultrafast -crf 51 -g 10 -bf 2 -pix_fmt yuv420p \
///       -c:a aac -b:a 8k -ac 1 -frag_duration 1000000 -movflags default_base_moof lazy.mp4
@Suite(.timeLimit(.minutes(1)))
struct LazyFragIndexTests {

    private struct Packet: Equatable, CustomStringConvertible {
        var stream: Int32
        var pts: Int64
        var dts: Int64
        var size: Int32
        var key: Bool
        var description: String { "s\(stream) pts \(pts) dts \(dts) size \(size)\(key ? " key" : "")" }
    }

    private static func withFile<T>(_ body: (String) throws -> T) throws -> T {
        let data = try #require(Data(base64Encoded: fixture, options: .ignoreUnknownCharacters))
        let path = FileManager.default.temporaryDirectory
            .appendingPathComponent("mov-lazy-frag-index-\(UUID().uuidString).mp4").path
        try data.write(to: URL(fileURLWithPath: path))
        defer { try? FileManager.default.removeItem(atPath: path) }
        return try body(path)
    }

    private static func open(_ path: String, lazy: Bool) throws -> UnsafeMutablePointer<AVFormatContext> {
        var options: OpaquePointer?
        if lazy { av_dict_set(&options, "lazy_frag_index", "1", 0) }
        defer { av_dict_free(&options) }
        var ctxIn: UnsafeMutablePointer<AVFormatContext>?
        try #require(avformat_open_input(&ctxIn, path, nil, &options) == 0)
        #expect(av_dict_count(options) == 0, "the mov demuxer consumed the option")
        return try #require(ctxIn)
    }

    private static func durations(lazy: Bool) throws -> [Int64] {
        try withFile { path in
            var ctx: UnsafeMutablePointer<AVFormatContext>? = try open(path, lazy: lazy)
            defer { avformat_close_input(&ctx) }
            return (0..<Int(ctx!.pointee.nb_streams)).map { ctx!.pointee.streams[$0]!.pointee.duration }
        }
    }

    /// Seeks one stream and returns the packets that follow.
    private static func seek(lazy: Bool, stream: Int32, seconds: Double, flags: Int32) throws -> [Packet] {
        try withFile { path in
            var ctx: UnsafeMutablePointer<AVFormatContext>? = try open(path, lazy: lazy)
            defer { avformat_close_input(&ctx) }
            let tb = ctx!.pointee.streams[Int(stream)]!.pointee.time_base
            let ts = Int64(seconds * Double(tb.den) / Double(tb.num))
            try #require(av_seek_frame(ctx, stream, ts, flags) >= 0)
            var packet = av_packet_alloc()
            defer { av_packet_free(&packet) }
            var packets: [Packet] = []
            while packets.count < 40, av_read_frame(ctx, packet) >= 0 {
                let p = packet!.pointee
                packets.append(Packet(stream: p.stream_index, pts: p.pts, dts: p.dts, size: p.size,
                                      key: p.flags & AV_PKT_FLAG_KEY != 0))
                av_packet_unref(packet)
            }
            return packets
        }
    }

    @Test("the streams get the durations of the full index")
    func durations() throws {
        let full = try Self.durations(lazy: false)
        #expect(full.count == 2)
        #expect(try Self.durations(lazy: true) == full)
    }

    @Test("a seek lands where the full index lands", arguments: [
        (Int32(0), 2.2, AVSEEK_FLAG_BACKWARD),                      // read on into a fragment its own successor
        (Int32(0), 0.5, Int32(0)),
        (Int32(0), 7.0, AVSEEK_FLAG_BACKWARD | AVSEEK_FLAG_ANY),
        (Int32(1), 4.3, Int32(0)),                                  // video must start on a sync sample
        (Int32(1), 6.6, AVSEEK_FLAG_BACKWARD),
        (Int32(1), 2.2, AVSEEK_FLAG_ANY),
    ])
    func seek(stream: Int32, seconds: Double, flags: Int32) throws {
        let full = try Self.seek(lazy: false, stream: stream, seconds: seconds, flags: flags)
        let lazy = try Self.seek(lazy: true, stream: stream, seconds: seconds, flags: flags)
        #expect(lazy == full)
        #expect(lazy.first { $0.stream == 0 }?.key == true || flags & AVSEEK_FLAG_ANY != 0,
                "the video starts on a sync sample")
    }

